use std::collections::BTreeMap;
use std::io::Read;

enum V {
    Null,
    Bool,
    Num(f64, bool),
    Str(String),
    Arr(Vec<V>),
    Obj(Vec<(String, V)>),
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn lit(&mut self, s: &str) -> Option<()> {
        if self.b[self.i..].starts_with(s.as_bytes()) {
            self.i += s.len();
            Some(())
        } else {
            None
        }
    }
    fn val(&mut self, d: usize) -> Option<V> {
        if d > 100 {
            return None;
        }
        self.ws();
        match self.peek()? {
            b'n' => self.lit("null").map(|_| V::Null),
            b't' => self.lit("true").map(|_| V::Bool),
            b'f' => self.lit("false").map(|_| V::Bool),
            b'"' => self.string().map(V::Str),
            b'[' => {
                self.i += 1;
                let mut v = Vec::new();
                self.ws();
                if self.peek()? == b']' {
                    self.i += 1;
                    return Some(V::Arr(v));
                }
                loop {
                    v.push(self.val(d + 1)?);
                    self.ws();
                    match self.peek()? {
                        b',' => self.i += 1,
                        b']' => {
                            self.i += 1;
                            return Some(V::Arr(v));
                        }
                        _ => return None,
                    }
                }
            }
            b'{' => {
                self.i += 1;
                let mut v = Vec::new();
                self.ws();
                if self.peek()? == b'}' {
                    self.i += 1;
                    return Some(V::Obj(v));
                }
                loop {
                    self.ws();
                    if self.peek()? != b'"' {
                        return None;
                    }
                    let k = self.string()?;
                    self.ws();
                    if self.peek()? != b':' {
                        return None;
                    }
                    self.i += 1;
                    let x = self.val(d + 1)?;
                    v.push((k, x));
                    self.ws();
                    match self.peek()? {
                        b',' => self.i += 1,
                        b'}' => {
                            self.i += 1;
                            return Some(V::Obj(v));
                        }
                        _ => return None,
                    }
                }
            }
            b'-' | b'0'..=b'9' => self.num(),
            _ => None,
        }
    }
    fn digits(&mut self) -> Option<()> {
        let s = self.i;
        while matches!(self.peek(), Some(b'0'..=b'9')) {
            self.i += 1;
        }
        if self.i > s {
            Some(())
        } else {
            None
        }
    }
    fn num(&mut self) -> Option<V> {
        let s = self.i;
        let mut int = true;
        if self.peek() == Some(b'-') {
            self.i += 1;
        }
        if self.peek()? == b'0' {
            self.i += 1;
        } else {
            self.digits()?;
        }
        if self.peek() == Some(b'.') {
            int = false;
            self.i += 1;
            self.digits()?;
        }
        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            int = false;
            self.i += 1;
            if matches!(self.peek(), Some(b'+') | Some(b'-')) {
                self.i += 1;
            }
            self.digits()?;
        }
        let t = std::str::from_utf8(&self.b[s..self.i]).ok()?;
        Some(V::Num(t.parse().ok()?, int))
    }
    fn hex4(&mut self) -> Option<u32> {
        let mut n = 0;
        for _ in 0..4 {
            let c = self.peek()?;
            n = n * 16 + (c as char).to_digit(16)?;
            self.i += 1;
        }
        Some(n)
    }
    fn string(&mut self) -> Option<String> {
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = self.peek()?;
            self.i += 1;
            match c {
                b'"' => return String::from_utf8(out).ok(),
                0..=0x1f => return None,
                b'\\' => {
                    let e = self.peek()?;
                    self.i += 1;
                    let ch = match e {
                        b'"' => '"',
                        b'\\' => '\\',
                        b'/' => '/',
                        b'b' => '\u{8}',
                        b'f' => '\u{c}',
                        b'n' => '\n',
                        b'r' => '\r',
                        b't' => '\t',
                        b'u' => {
                            let mut u = self.hex4()?;
                            if (0xD800..0xDC00).contains(&u) {
                                if self.b[self.i..].starts_with(b"\\u") {
                                    self.i += 2;
                                    let l = self.hex4()?;
                                    if (0xDC00..0xE000).contains(&l) {
                                        u = 0x10000 + ((u - 0xD800) << 10) + (l - 0xDC00);
                                    } else {
                                        return None;
                                    }
                                } else {
                                    return None;
                                }
                            } else if (0xDC00..0xE000).contains(&u) {
                                return None;
                            }
                            char::from_u32(u)?
                        }
                        _ => return None,
                    };
                    let mut buf = [0u8; 4];
                    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                }
                _ => out.push(c),
            }
        }
    }
}

fn get<'a>(o: &'a [(String, V)], k: &str) -> Option<&'a V> {
    o.iter().find(|(a, _)| a == k).map(|(_, v)| v)
}

fn process(v: &V, m: &mut BTreeMap<String, f64>) -> Option<()> {
    let arr = match v {
        V::Arr(a) => a,
        _ => return None,
    };
    for o in arr {
        let o = match o {
            V::Obj(o) => o,
            _ => return None,
        };
        match get(o, "id")? {
            V::Num(_, true) => {}
            _ => return None,
        }
        let cust = match get(o, "customer")? {
            V::Str(s) => s.clone(),
            _ => return None,
        };
        if let Some(n) = get(o, "note") {
            if !matches!(n, V::Str(_)) {
                return None;
            }
        }
        let items = match get(o, "items")? {
            V::Arr(a) => a,
            _ => return None,
        };
        let mut sum = 0.0;
        for it in items {
            let it = match it {
                V::Obj(o) => o,
                _ => return None,
            };
            if !matches!(get(it, "sku")?, V::Str(_)) {
                return None;
            }
            let q = match get(it, "qty")? {
                V::Num(n, true) => *n,
                _ => return None,
            };
            let p = match get(it, "price")? {
                V::Num(n, _) => *n,
                _ => return None,
            };
            sum += q * p;
        }
        *m.entry(cust).or_insert(0.0) += sum;
    }
    Some(())
}

fn run() -> Option<String> {
    let mut buf = Vec::new();
    std::io::stdin().read_to_end(&mut buf).ok()?;
    let s = std::str::from_utf8(&buf).ok()?;
    let s = s.strip_prefix('\u{feff}').unwrap_or(s);
    let mut p = P { b: s.as_bytes(), i: 0 };
    let v = p.val(0)?;
    p.ws();
    if p.i != p.b.len() {
        return None;
    }
    let mut m = BTreeMap::new();
    process(&v, &mut m)?;
    let mut out = String::new();
    for (k, t) in m {
        out.push_str(&format!("{} {:.2}\n", k, t));
    }
    Some(out)
}

fn main() {
    match run() {
        Some(o) => print!("{}", o),
        None => {
            println!("invalid input");
            std::process::exit(1);
        }
    }
}

